from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

OUT=Path(__file__).resolve().parent / 'Droid-Fun-Controller-Guide-0.4.0.pdf'
BLUE=colors.HexColor('#3268dc'); INK=colors.HexColor('#17283d'); MUTED=colors.HexColor('#526174'); PALE=colors.HexColor('#edf2f8')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleDF',fontName='Helvetica',fontSize=27,leading=30,textColor=INK,spaceAfter=12))
styles.add(ParagraphStyle(name='SectionDF',fontName='Helvetica-Bold',fontSize=13,leading=17,textColor=INK,spaceBefore=9,spaceAfter=5))
styles.add(ParagraphStyle(name='BodyDF',fontName='Helvetica',fontSize=10,leading=13,textColor=INK,spaceAfter=5))
styles.add(ParagraphStyle(name='SmallDF',fontName='Helvetica',fontSize=8.8,leading=11.4,textColor=MUTED,spaceAfter=5))
styles.add(ParagraphStyle(name='LabelDF',fontName='Helvetica-Bold',fontSize=9,leading=13,textColor=BLUE,spaceAfter=10))
story=[]
def p(s,style='BodyDF'):return Paragraph(s,styles[style])
def text(s):story.append(p(s))
def title(n,name,lead):story.extend([p('DROID FUN / '+n,'LabelDF'),p(name,'TitleDF'),p(lead)])
def section(name):story.append(p(name,'SectionDF'))
def steps(items):
 for i,s in enumerate(items,1):story.append(p('<b>%d.</b> %s'%(i,s)))
def box(s):
 t=Table([[p(s)]],colWidths=[492]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PALE),('BOX',(0,0),(-1,-1),0.5,colors.HexColor('#dce3ec')),('LEFTPADDING',(0,0),(-1,-1),14),('RIGHTPADDING',(0,0),(-1,-1),14),('TOPPADDING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.extend([t,Spacer(1,10)])
def table(rows,widths):
 t=Table([[p(s,'SmallDF') for s in row] for row in rows],colWidths=widths,hAlign='LEFT');t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),PALE),('LINEBELOW',(0,0),(-1,0),0.6,colors.HexColor('#cbd6e3')),('LINEBELOW',(0,1),(-1,-1),0.35,colors.HexColor('#dce3ec')),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),4)]));story.append(t)
def new():story.append(PageBreak())

title('01 / GET STARTED','Your droid, your way.','The controller setup guide for <b>DroidFun App 0.4.0</b>.<br/>Guide 1.4 / October 16, 2026 / Robot firmware 1.2.0.')
box("""<b>New in this update</b><br/>Choose your bot, design custom text screens, and save text and still faces to Boo or Meep for USB wall power. Claw keeps its dedicated Claude and Codex usage screens.""")
section('Choose your bot')
text("""When you first open this update, select <b>Boo Bot</b>, <b>Claw Bot</b> or <b>Meep Bot</b>. The choice is remembered. Use <b>Change bot</b> any time; screens for your other bots stay saved and reappear when you switch back.""")
table([['<b>Bot</b>','<b>Available screens</b>'],['Boo Bot and Meep Bot','Custom text, faces, clocks, focus timers, meeting countdowns, weather, stocks, CPU and memory.'],['Claw Bot','Claude and Codex account allowance screens. Boo/Meep widgets are hidden.']],[160,332])
section('Before you begin')
text("""Use a desktop computer, a USB <b>data</b> cable, and a compatible robot: <b>RP2040-Zero with a 128 x 64 SSD1306 OLED</b>, SDA GPIO 4, SCL GPIO 5, address 0x3C. Firmware 1.2.0 adds storage for wall-powered screens. Confirm this electronics profile before installing firmware.""")
text("""You can explore the app preview without hardware. The app controls the screen and its playlist; it does not operate motors or move a claw. Live data requires the computer and internet. Saved text and still faces can run from USB wall power after a successful save.""")
section('Choose your installer')
table([['<b>Computer</b>','<b>Download type</b>'],['Mac, macOS 13 or later','Universal DMG for Apple Silicon and Intel'],['Intel/AMD Windows PC','Windows x64 installer'],['Windows on ARM / Snapdragon','Windows ARM64 installer'],['Ubuntu/Debian, Intel/AMD 64-bit','Linux x86_64 DEB'],['RPM-based Linux, Intel/AMD 64-bit','Linux x86_64 RPM']],[210,282])
text("""Get the matching version from <link href="https://droidfun.io/downloads" color="#3268dc">droidfun.io/downloads</link>. Normal use needs no Node.js, Rust, Git or repository access. This guide describes 0.4.0; check the version shown on the download page.""")
story.append(p('Development packages: Mac is not Developer ID signed or notarized; Windows installers are unsigned. Physical USB upload and wall-charger power-cycle verification for the new saved-screen feature remain outstanding. See release notes for platform verification limits.','SmallDF'))

new();title('02 / INSTALL + CONNECT','Say hello over USB.','Install the app, choose your bot, and connect its screen.')
section('Install')
text("""<b>Mac:</b> Quit the old controller first. If upgrading from Deskbot, turn off its Start at login setting before quitting. Open the DMG, copy <b>DroidFun App.app</b> to Applications, and launch it there. Use this stable location before enabling Start at login again.""")
text("""<b>Windows:</b> Run the installer matching your CPU architecture. The app installs for your current user. The interface requires WebView2; follow any missing-runtime instructions from the installer.""")
text("""<b>Linux:</b> On Ubuntu, open the DEB in a graphical package installer and approve installation. The package includes the libraries and robot USB-access setup. For RPM distributions, use the distribution’s package manager. Run DroidFun App as your normal user.""")
box("""If macOS, Windows or your organization blocks an unsigned development package, request a signed build. Do not disable system protections as a routine installation step.""")
section('First launch')
steps(['Open <b>DroidFun App</b> and choose your bot. Existing settings and widgets are retained when you upgrade; only the selected bot’s screens appear.','For Boo or Meep, try <b>Add widget &gt; Custom text</b> or edit a face. For Claw, add a Claude or Codex allowance screen. Account connections are optional; sample data can be previewed.','Connect your robot when you are ready. You can use the on-screen preview without it.'])
section('Connect a robot')
steps(['Plug the robot into the computer with a USB data cable. A charge-only cable cannot connect the app.','Under <b>Connection</b>, choose <b>Scan USB</b>, find the intended RP2040-Zero, then choose <b>Connect</b>.','Wait for <b>connected</b>. Check the firmware and OLED status. Select an enabled widget and choose <b>Show now</b>.','Look at the physical screen to confirm the content is readable. The connection status alone cannot establish this.'])
section('If USB access needs attention')
text("""Try another data cable or port and close any other app using the device. On Linux, choose <b>Connection &gt; Set up robot access</b>, approve the desktop administrator prompt, then unplug/reconnect if needed. This helper expects a local desktop with systemd-logind, udev and polkit.""")
text("""If the app reports <b>setup_needed</b> or asks for newer firmware, follow page 5 after confirming the hardware profile. A board running another sketch will not understand the controller protocol.""")

new();title('03 / CUSTOM SCREENS','Make it say something.','Custom text and face screens are available for Boo Bot and Meep Bot.')
section('Create a text screen')
steps(['Choose <b>Add widget &gt; Custom text &gt; Add</b>. Give the screen a short name so you can find it later.','Enter <b>Your text</b>. Use up to 128 characters: English letters, numbers, spaces and basic punctuation (printable ASCII). Press Return for a new line. Emojis and accented characters are not supported by this screen font.','Choose Small or Large text, horizontal alignment and vertical position. Add a border or invert the screen colors if you like.','Check the <b>128 x 64 screen preview</b>. It uses the same renderer as the bot. If the text will not fit, shorten it, choose Small, or remove the border. Your draft stays in the editor so you can fix it.','Choose <b>Apply</b>, enable the screen and set <b>Show for</b>. Select the row to preview it; choose <b>Show now</b> to display it for one turn.'])
box("""<b>Try this</b><br/>Type <b>Hello, human!</b> on one line and <b>Have a nice day.</b> on the next. Choose Small text, centered both ways, then preview. The name is for your playlist; <b>Your text</b> is what appears on the OLED.""")
section('Choose a face')
text("""Add a <b>Face</b> widget or edit an existing one. Choose Happy, Neutral, Sleepy or Surprised, plus blink and animation speed. Add separate face screens for different expressions. The original face remains available; added face widgets can be removed.""")
text("""Faces animate while the desktop app supplies the display, subject to reduced-motion and pause settings. For wall-powered playback, each face is stored as a still image of the selected expression.""")
section('Style a data screen')
text("""In a data widget’s editor, choose <b>Classic</b> for a detailed layout or <b>Minimal</b> for centered content. Toggle <b>Show companion face</b> and <b>Invert screen colors</b>. These controls are available for the selected bot’s data widgets, including Claw’s allowance screens.""")
text("""The companion also follows the global <b>Settings &gt; Display &gt; Small smile on data widgets</b> setting. Text screens use their own size and alignment controls; faces use expression controls.""")
section('Preview, then save')
text("""The editor previews your draft without changing the live playlist. <b>Apply</b> saves it to the app. To replace the separate copy stored on your bot for wall power, use <b>Save to bot</b> afterward; see page 5.""")

new();title('04 / PLAYLIST + WIDGETS','A screen for your day.','Enable, order and time the screens that belong to your selected bot.')
section('Build the cycle')
text("""Switch a widget on to include it. Set <b>Show for</b> between 3 and 120 seconds, then drag it or use the up/down arrows. <b>Add widget</b> creates another screen; <b>Edit</b> changes its content and style. You can keep up to 30 widgets across bot profiles.""")
table([['<b>Control</b>','<b>What happens</b>'],['Select a row','The app previews that screen; the robot cycle continues.'],['Show now / Pin','Show an enabled screen for one turn, or hold it until you resume.'],['Pause / Resume / Next','Pause the cycle, continue it, or advance to the next usable screen.'],['Back to live cycle','Return the app preview to the robot’s current screen.']],[165,327])
section('Boo and Meep: local widgets')
table([['<b>Widget</b>','<b>Settings and behavior</b>'],['Clock','Time zone, 12/24-hour format, seconds and date.'],['Focus timer','Focus and break lengths, sessions before a long break; Start, Pause, Reset and Skip phase beside the row.'],['Meeting countdown','Manual title, local date/time and duration. Shows NOW during the meeting, then DONE.'],['Computer CPU / Memory','CPU sampling/history, or used/available RAM with GB/GiB units. These describe your computer, not the robot.']],[145,347])
text("""Local widgets need no internet, but the desktop app must supply their screen. Timers retain their start time across app closure and catch up on reopening. They do not sound an alarm or run as a wall-powered clock. Changing timer lengths resets it to paused.""")
section('Boo and Meep: weather and stocks')
text("""<b>Weather:</b> Edit, choose <b>Live data</b>, enter a city, choose <b>Find city</b>, select a result, then set units and layout. <b>Stocks:</b> Edit, choose <b>Live data</b>, enter a symbol such as MSFT, and optionally show price change. Add a separate widget for another city or symbol.""")
text("""Enabled weather and stocks normally refresh every 15 minutes. Open-Meteo supplies weather; its free hosted service is for personal, non-commercial use. Yahoo Finance quotes need no API key, include a date/currency and may be delayed.""")
section('Pause online data')
text("""This stops internet requests while USB and local widgets continue; it does not save screens to the robot. Saved preview values are not fresh readings. Resume online data to search locations or connect accounts. Samples are labeled, and unavailable live widgets are skipped.""")

new();title('05 / USB WALL POWER','Save it. Then unplug.','Boo and Meep can store text and still face screens with firmware 1.2.0.')
section('Save your screens to the bot')
steps(['Connect Boo or Meep to the computer with a USB data cable. Confirm the app shows <b>connected</b> and firmware <b>1.2.0</b> or newer.','Enable the text and face screens you want, choose their order and durations, and set brightness and screen orientation.','Under <b>Use without a computer</b>, check the ready-to-save count and choose <b>Save to bot</b>. Keep the cable connected and wait for the success message. An error or timeout does not confirm a save.','After success, unplug the bot from the computer and connect it to a USB wall charger. Check that the expected screens cycle. Unplug and reconnect wall power to confirm they remain stored.'])
box("""<b>What is stored?</b><br/>Up to 30 enabled text and still face screens, each shown for 3-120 seconds, plus brightness and orientation. Saving again replaces the stored playlist. Editing or deleting a screen in the app does not change the stored copy until you save again.""")
section('What still needs your computer')
text("""Weather, stocks, clocks, timers, computer statistics, and Claude/Codex usage are <b>not</b> saved for wall-powered playback. They need DroidFun App running and USB connected; live sources also need internet. Claw Bot does not offer Save to bot because its allowance screens depend on the computer.""")
section('Update firmware if the app asks')
text("""Only use this firmware for the RP2040-Zero / SSD1306 profile on page 1. In <b>Settings &gt; Robot &gt; Install firmware manually</b>, choose <b>Save robot firmware</b>. Version 0.4.0 exports firmware <b>1.2.0</b>.""")
steps(['Preserve the original program/source or flash backup if you need it. Copying a UF2 replaces the board’s program; plan to save your desired screens again afterward.','Unplug the robot, hold its <b>BOOT</b> button, and reconnect USB. Release BOOT when the <b>RPI-RP2</b> drive appears.','Copy the exported UF2 file to that drive. Wait for the robot to restart, then return to Connection, scan and connect.','Check the firmware version and physical OLED. Then use <b>Save to bot</b> and verify the wall-power behavior described above.'])
story.append(p('The app confirms only after the bot acknowledges a complete save. Physical USB upload and wall-charger power-cycle testing of this new feature remain outstanding in the release evidence. Confirm it on your bot before relying on standalone playback.','SmallDF'))

new();title('06 / CLAW BOT','Allowance at a glance.','Choose Claw Bot for Claude and Codex screens. Boo and Meep do not expose these account integrations.')
section('Connect Codex')
steps(['Install and sign in to the Codex CLI separately with your own account. DroidFun App reads that existing sign-in.','Add or edit a <b>Codex allowance</b> widget and choose <b>Live data</b>. Ensure Pause online data is off.','Choose <b>Read account windows</b>, select a window returned by your account, then <b>Apply</b>. If detection fails, expand <b>CLI location</b> and enter the executable path.'])
text("""The app reads allowance percentages, not remaining token counts, without starting a model turn. It refreshes at most every five minutes. If an account returns no window, that screen is unavailable; the app does not invent a zero.""")
section('Connect Claude')
steps(['Add or edit a <b>Claude allowance</b> widget, choose <b>Live data</b>, and select a five-hour or seven-day allowance window.','For Usage source, choose <b>Shared Claude account (desktop, web and Code)</b>.','Use your existing Claude Code sign-in, or choose <b>Connect Claude account</b> and finish browser sign-in. Then <b>Apply</b>.'])
text("""This reads the shared allowance without sending a prompt and normally refreshes every five minutes. Initial or revoked sign-ins and interactive onboarding need your action. To use a separate profile, expand <b>Another Claude account profile</b>.""")
text("""<b>Windows recovery:</b> Requires native claude.exe and Windows 10 version 1809 or later (or Server 2019+). The recovery path does not support a WSL-only installation. Follow the reconnect message if recovery fails.""")
section('Optional: Claude Code status-line reports')
text("""Choose <b>Claude Code status-line report</b> for the optional local bridge. Review <b>Proposed integration</b> before enabling it. The app backs up and chains the existing command; <b>Restore original status line</b> removes the integration.""")
text("""Reports arrive after eligible Claude Code activity and become stale after 10 minutes. Missing reports mean waiting. Advanced report folder, profile and session selectors are optional.""")
section('Use and style your allowance screens')
text("""Enable each screen and choose its duration. Edit its Classic/Minimal layout, companion face and inversion. Samples are clearly labeled. Live readings need the app, USB and the data source; they cannot be saved to a wall-powered Claw Bot.""")
text("""Use your own accounts. Installers contain no local sign-ins or user settings. DroidFun App does not persist prompts or transcripts. Review diagnostics before choosing to share them.""")

new();title('07 / SETTINGS + HELP','Keep it comfortable.','Your settings stay on your computer. Your saved wall-power playlist stays on the bot.')
section('Display and appearance')
text("""Use <b>Display</b> for brightness and screen on/off. Boo and Meep also offer <b>Show face</b>. In <b>Settings &gt; Display</b>, adjust orientation, the companion animation and quiet hours, then choose <b>Apply settings</b>. Quiet hours follow the computer’s local time. <b>Wake for 15 minutes</b> temporarily overrides them; manual screen-off takes priority.""")
text("""Quiet hours, playlist pause and animated faces are desktop features. They are not stored for wall power. Save to bot stores the current brightness and orientation; save again after changing either if you want the wall-powered display to match.""")
text("""Choose <b>DroidFun - blue</b> or <b>Classic - green</b> in Branding. In <b>Settings &gt; App</b>, choose light/dark/system appearance and how the controls behave when closed. The main Branding dropdown applies immediately; changes inside Settings need Apply settings.""")
section('Keep the app running, or quit')
text("""Mac uses the menu bar; Windows uses the notification area. Linux needs a compatible tray host or keeps a normal window available. Relaunching DroidFun App reopens the controls. Start at login is opt-in. Turn it off and quit the app before manually removing the app on Mac or Linux.""")
section('Troubleshooting')
table([['<b>Symptom</b>','<b>Try this</b>'],['Save to bot is unavailable','Choose Boo or Meep, enable at least one text/face screen, connect USB, and check firmware 1.2.0+.'],['Old screens on wall power','Editing the app does not update the stored copy. Reconnect, choose Save to bot and wait for confirmation.'],['Text cannot be applied','Read the preview error. Use supported characters, shorten text, reduce its size or remove the border.'],['No USB connection','Try a data cable or different port, scan and select the robot. Close other apps using it; repair Linux access if needed.'],['OLED blank','Check brightness, screen on/off, quiet hours, playback and OLED health. For wall power, save with nonzero brightness.'],['Live data unavailable','Resume online data and check network/source/sign-in. Try a labeled sample to isolate display issues.'],['Need help','Settings > App > Preview diagnostics. Review, then Save reviewed report. Share it deliberately with the maker.']],[154,338])
section('Updates and reset')
text("""No automatic updater is enabled. Return to the Droid Fun Downloads page for later versions. Reset playlist and preferences creates a local settings backup and preserves account sign-ins. It resets the app’s playlist; a previously stored bot playlist is separate.""")

def frame(c,doc):
 c.setStrokeColor(colors.HexColor('#dce3ec'));c.line(54,752,558,752)
 c.setFillColor(BLUE);c.setFont('Helvetica-Bold',9);c.drawString(54,766,'droid fun.')
 c.setFillColor(MUTED);c.setFont('Helvetica',8);c.drawRightString(558,766,'APP 0.4.0  |  FIRMWARE 1.2.0')
 c.line(54,40,558,40);c.drawString(54,27,'Droid Fun  |  Guide 1.4  |  October 16, 2026');c.drawRightString(558,27,str(doc.page))
doc=SimpleDocTemplate(str(OUT),pagesize=(612,792),leftMargin=54,rightMargin=54,topMargin=58,bottomMargin=53,title='Droid Fun Controller Guide - App 0.4.0',author='Droid Fun',subject='Bot setup, custom screens and saved USB wall-power screens')
doc.build(story,onFirstPage=frame,onLaterPages=frame)
print(OUT)
